<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}require __DIR__.'/../core/init.php';session_save_path(sys_get_temp_dir());session_start();
function verify($condition,$message){if(!$condition)throw new RuntimeException($message);echo 'PASS '.$message."\n";}
$admin=sc_query('SELECT userid FROM users WHERE user_group=1 AND is_active=1 AND is_deleted=0 LIMIT 1')->get_result()->fetch_assoc();if(!$admin)exit('No superadmin fixture available.');$_SESSION[USER_AUTH]=$admin['userid'];$csrf=sc_csrf();$tag='sc-test-'.bin2hex(random_bytes(5));$categoryId=0;$productId=0;$orderId=0;
try {
 $r=sc_save_catalog(['csrf'=>$csrf,'category_name'=>$tag,'slug'=>$tag,'color_code'=>'#173e35'],true,false);verify($r['status']==='success','category creation');$categoryId=$r['id'];$edit=sc_save_catalog(['csrf'=>$csrf,'id'=>$categoryId,'category_name'=>$tag,'slug'=>$tag,'color_code'=>'#247050'],true,true);verify($edit['status']==='success','category edit');
 $duplicate=sc_save_catalog(['csrf'=>$csrf,'category_name'=>$tag,'slug'=>$tag,'color_code'=>'#173e35'],true,false);verify($duplicate['status']==='failed','duplicate category rejected');
 $data=['csrf'=>$csrf,'category_id'=>$categoryId,'product_name'=>$tag,'slug'=>$tag,'type'=>3,'product_color'=>'Green','price'=>100,'discounted_price'=>90,'tax1_percent'=>2.5,'tax2_percent'=>2.5,'igst_percent'=>5];$r=sc_save_catalog($data,false,false);verify($r['status']==='success','product creation with zero inventory');$productId=$r['id'];verify(sc_available($productId)===0,'new product starts out of stock');
 $bad=$data;$bad['id']=$productId;$bad['price']=-1;$r=sc_save_catalog($bad,false,true);verify($r['status']==='failed','invalid product price rejected');
 $data['id']=$productId;$r=sc_save_catalog($data,false,true);verify($r['status']==='success','product edit');
 $stock=['csrf'=>$csrf,'site_id'=>sc_stock_site(),'product_id'=>$productId,'change_quantity'=>3,'remarks'=>$tag];$r=sc_add_stock($stock);verify($r['status']==='success','stock receipt');verify(sc_available($productId)===3,'stock balance after receipt');
 $stock['change_quantity']=-2;verify(sc_add_stock($stock)['status']==='failed','negative stock receipt rejected');
 sc_query("INSERT INTO web_orders (order_number,online_user_id,checkout_token,delivery,subtotal,tax,total,payment_method,payment_status,status) VALUES (?,0,?,'{}',180,9,189,'cod','unpaid','placed')",'ss',[$tag,bin2hex(random_bytes(32))]);$orderId=sc_db()->insert_id;
 $p=sc_product($productId);$p['quantity']=2;sc_db()->begin_transaction();sc_stock_deduct($orderId,[$p]);sc_db()->commit();verify(sc_available($productId)===1,'order deducts actual stock');
 sc_db()->begin_transaction();$blocked=false;try{sc_stock_deduct($orderId,[$p]);}catch(RuntimeException $e){$blocked=true;}sc_db()->rollback();verify($blocked&&sc_available($productId)===1,'overselling blocked without changing stock');
 sc_stock_cancel($orderId,1);verify(sc_available($productId)===3,'cancelled order restores stock');sc_stock_cancel($orderId,1);verify(sc_available($productId)===3,'repeated cancellation does not double restock');
 unset($_SESSION[USER_AUTH]);verify(sc_add_stock($stock)['status']==='failed','unauthenticated stock changes rejected');
}finally{sc_db()->rollback();if($orderId){sc_query('DELETE FROM web_order_stock WHERE order_id=?','i',[$orderId]);sc_query('DELETE FROM web_orders WHERE id=?','i',[$orderId]);}if($productId){sc_query('DELETE FROM inventory_transactions WHERE product_id=?','i',[$productId]);sc_query('DELETE FROM inventory WHERE product_id=?','i',[$productId]);sc_query('DELETE FROM products WHERE id=?','i',[$productId]);}if($categoryId)sc_query('DELETE FROM product_categories WHERE id=?','i',[$categoryId]);session_destroy();echo "Temporary catalog and stock fixtures removed.\n";}
